rw("src/lib/queries.ts", lambda s: s.replace("  weather_recent: {", '''  bom_headers: { sql: "select h.*, p.name as sku_name, (select count(*) from bom_lines l where l.bom_id=h.id) as n_lines from bom_headers h join products p on p.sku=h.sku where h.farm_id=$1 order by h.sku, h.version desc" },
  bom_lines: { sql: "select l.*, p.name as component_name, exists(select 1 from bom_headers b where b.sku=l.component_sku and b.status='BAN_HANH') as has_bom from bom_lines l join products p on p.sku=l.component_sku where l.bom_id=$2 order by l.seq", params: ["bom"] },
  mrp_explode: { sql: "select * from mrp_explode($1, $2, $3::numeric)", params: ["sku", "qty"] },
  mrp_run: { sql: "select m.*, exists(select 1 from bom_headers b where b.farm_id=$1 and b.sku=m.component_sku and b.status='BAN_HANH') as has_bom from mrp_run($1, coalesce($2::int, 14)) m", params: ["days"] },
  production_plans: { sql: "select pp.*, p.name as sku_name from production_plans pp join products p on p.sku=pp.sku where pp.farm_id=$1 and pp.status<>'HUY' order by pp.week_start desc, pp.sku" },
  packaging_specs: { sql: "select ps.*, p.name as sku_name from packaging_specs ps join products p on p.sku=ps.sku where ps.status='ACTIVE' order by ps.sku, array_position(array['SO_CAP','THU_CAP','VAN_CHUYEN'], ps.level)" },
  label_specs: { sql: "select ls.*, p.name as sku_name from label_specs ls join products p on p.sku=ls.sku where ls.status<>'NGUNG' order by ls.sku, ls.market, ls.version desc" },
  allergens: { sql: "select * from allergens order by code" },
  lot_labels: { sql: "select * from v_lot_label where farm_id=$1 order by mfg_date desc nulls last limit 200" },
  pack_batches: { sql: "select * from v_pack_batches where farm_id=$1 order by ts desc limit 300" },
  weather_recent: {''',1))
