def pr(s):
    s=s.replace('import { getSession }', 'import { qrSvg, publicBase } from "@/lib/qr";\nimport { getSession }',1)
    old='  else if (kind === "bm") {'
    new='''  else if (kind === "tem") { const n = Math.min(Number((await searchParams).n ?? 24), 200); const rows = await q("select * from v_lot_label where lot_id=$1", [id]); const l = rows[0]; if (!l) body = <p>Không thấy lô {id}.</p>; else { const svg = await qrSvg(publicBase() + "/trace/" + l.lot_id, 140); const al = (l.allergens as string[] | null) ?? []; const nut = (l.nutrition as Record<string, unknown>) ?? {}; body = <div className="grid grid-cols-2 gap-2">{Array.from({ length: n }).map((_, i) => <div key={i} className="border border-black p-2 h-[62mm] flex gap-2 break-inside-avoid text-[9px] leading-tight"><div className="w-[34mm] shrink-0"><div dangerouslySetInnerHTML={{ __html: svg }} /><div className="font-mono text-[8px] text-center mt-1">{String(l.lot_id)}</div></div><div className="flex-1"><div className="font-black text-[12px]">{String(l.product_name ?? l.sku_name)}</div><div><b>Thành phần:</b> {String(l.ingredients ?? "")}</div>{al.length > 0 && <div><b>Chứa:</b> {al.join(", ")}</div>}{Array.isArray(l.may_contain) && (l.may_contain as string[]).length > 0 && <div>Có thể chứa: {(l.may_contain as string[]).join(", ")}</div>}<div><b>KL tịnh:</b> {String(l.net_content ?? "")}</div><div><b>NSX:</b> {String(l.mfg_date ?? "").slice(0, 10)} · <b>HSD:</b> {String(l.expiry_date ?? "").slice(0, 10)}</div><div><b>Bảo quản:</b> {String(l.storage ?? "")}</div>{l.usage_instr ? <div><b>HDSD:</b> {String(l.usage_instr)}</div> : null}{Object.keys(nut).length > 0 && <div><b>Dinh dưỡng/{String(nut.per ?? "100g")}:</b> {Object.entries(nut).filter(([k]) => k !== "per").map(([k, v]) => `${k.replace(/_/g, " ")} ${String(v)}`).join(" · ")}</div>}<div><b>SX:</b> {String(l.producer)} · {String(l.address ?? "")} {l.hotline ? `· ${String(l.hotline)}` : ""}</div><div>Xuất xứ: {String(l.origin ?? "Việt Nam")}{l.gtin ? ` · GTIN ${String(l.gtin)}` : ""}</div>{Array.isArray(l.std_marks) && (l.std_marks as string[]).length > 0 && <div className="font-bold">{(l.std_marks as string[]).join(" · ")}{l.halal ? " · HALAL" : ""}{l.organic ? " · HỮU CƠ" : ""}</div>}{Array.isArray(l.claims) && (l.claims as string[]).length > 0 && <div className="italic">{(l.claims as string[]).join(" · ")}</div>}<div className="mt-1">Quét QR để truy xuất nguồn gốc lô</div></div></div>)}</div>; } }
  else if (kind === "bm") {'''
    assert old in s; s=s.replace(old,new,1)
    s=s.replace('const base = process.env.PUBLIC_URL ?? ""; body = <div className="grid grid-cols-3 gap-2">{lots.map((l) => <div key={String(l.id)} className="border border-black p-2 h-[40mm] flex gap-2 items-center break-inside-avoid"><img alt="QR" className="h-[32mm] w-[32mm]" src={`https://api.qrserver.com/v1/create-qr-code/?size=160x160&data=${encodeURIComponent(base + "/trace/" + l.id)}`} />',
                'const base = publicBase(); const svgs = await Promise.all(lots.map((l) => qrSvg(base + "/trace/" + l.id, 120))); body = <div className="grid grid-cols-3 gap-2">{lots.map((l, i) => <div key={String(l.id)} className="border border-black p-2 h-[40mm] flex gap-2 items-center break-inside-avoid"><div className="h-[32mm] w-[32mm]" dangerouslySetInnerHTML={{ __html: svgs[i] }} />',1)
    s=s.replace('searchParams: Promise<{ farm?: string }>','searchParams: Promise<{ farm?: string; n?: string }>',1)
    s=s.replace('  if (kind === "nhan-lo") size = "A4";','  if (kind === "nhan-lo" || kind === "tem") size = "A4";',1)
    return s
